using AdDatabase.BLL.Entities; using Microsoft.EntityFrameworkCore;
namespace AdDatabase.DAL.Data;
public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options):DbContext(options){
 public DbSet<User> Users=>Set<User>(); public DbSet<Role> Roles=>Set<Role>(); public DbSet<Profile> Profiles=>Set<Profile>(); public DbSet<Session> Sessions=>Set<Session>(); public DbSet<VerificationCode> VerificationCodes=>Set<VerificationCode>(); public DbSet<City> Cities=>Set<City>(); public DbSet<Region> Regions=>Set<Region>(); public DbSet<Category> Categories=>Set<Category>(); public DbSet<Ad> Ads=>Set<Ad>(); public DbSet<AdImage> AdImages=>Set<AdImage>(); public DbSet<AdAttribute> AdAttributes=>Set<AdAttribute>(); public DbSet<AdTag> AdTags=>Set<AdTag>(); public DbSet<Tag> Tags=>Set<Tag>(); public DbSet<Business> Businesses=>Set<Business>(); public DbSet<BusinessCategory> BusinessCategories=>Set<BusinessCategory>(); public DbSet<BusinessItem> BusinessItems=>Set<BusinessItem>(); public DbSet<ItemImage> ItemImages=>Set<ItemImage>(); public DbSet<Conversation> Conversations=>Set<Conversation>(); public DbSet<Message> Messages=>Set<Message>(); public DbSet<MessageAttachment> MessageAttachments=>Set<MessageAttachment>(); public DbSet<Comment> Comments=>Set<Comment>(); public DbSet<Rating> Ratings=>Set<Rating>(); public DbSet<AdFavorite> AdFavorites=>Set<AdFavorite>(); public DbSet<Follow> Follows=>Set<Follow>(); public DbSet<News> News=>Set<News>(); public DbSet<Notification> Notifications=>Set<Notification>(); public DbSet<Report> Reports=>Set<Report>(); public DbSet<Request> Requests=>Set<Request>(); public DbSet<SearchHistory> SearchHistories=>Set<SearchHistory>(); public DbSet<Verification> Verifications=>Set<Verification>();
 protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);
  b.Entity<User>().HasIndex(x=>x.Email).IsUnique();b.Entity<User>().HasIndex(x=>x.UserName).IsUnique();b.Entity<Role>().HasIndex(x=>x.Name).IsUnique();b.Entity<Profile>().HasIndex(x=>x.UserId).IsUnique();b.Entity<User>().HasOne(x=>x.Profile).WithOne(x=>x.User).HasForeignKey<Profile>(x=>x.UserId).OnDelete(DeleteBehavior.Cascade);
  b.Entity<Category>().HasOne(x=>x.Parent).WithMany(x=>x.Children).HasForeignKey(x=>x.ParentCategoryId).OnDelete(DeleteBehavior.Restrict);
  b.Entity<Ad>().Property(x=>x.Price).HasPrecision(18,2);b.Entity<BusinessItem>().Property(x=>x.Price).HasPrecision(18,2);
  b.Entity<AdTag>().HasKey(x=>new{x.AdId,x.TagId});b.Entity<AdFavorite>().HasKey(x=>new{x.UserId,x.AdId});b.Entity<Follow>().HasKey(x=>new{x.FollowerUserId,x.FollowedUserId});b.Entity<BusinessCategory>().HasIndex(x=>new{x.BusinessId,x.CategoryId}).IsUnique();
  b.Entity<Rating>().ToTable(t=>{t.HasCheckConstraint("CHK_Ratings_NoSelfRating","[UserId] <> [RatedUserId]");t.HasCheckConstraint("CHK_Ratings_Value","[Value] BETWEEN 1 AND 5");});b.Entity<Follow>().ToTable(t=>t.HasCheckConstraint("CHK_Follows_NoSelf","[FollowerUserId] <> [FollowedUserId]"));
  b.Entity<Conversation>().HasIndex(x=>new{x.AdId,x.BuyerUserId,x.SellerUserId}).IsUnique();b.Entity<AdImage>().HasIndex(x=>new{x.AdId,x.SortOrder}).IsUnique();b.Entity<Tag>().HasIndex(x=>x.Name).IsUnique();
  b.Entity<Role>().HasData(new Role{Id=1,Name="Admin"},new Role{Id=2,Name="User"});
 }
}
